def run_calibration_study():
    judge = LLMJudge()
    human_scores = []
    judge_scores = []

    for item in CALIBRATION_PAIRS:
        eval_res = judge.evaluate_reply(
            customer_tweet=item["tweet"],
            generated_reply=item["reply"],
            gold_reply=item["gold"],
            true_escalate=item["true_esc"],
            pred_escalate=item["pred_esc"],
            intent=item["intent"]
        )
        human_scores.append(item["human_rating"])
        judge_scores.append(eval_res["composite_score"])

    stats = HumanJudgeAgreementAnalyzer.compute_agreement(human_scores, judge_scores)
    return stats

if __name__ == "__main__":
    stats = run_calibration_study()
    print(HumanJudgeAgreementAnalyzer.format_summary_table(stats))
